-- Word Efficiency Tests 4 and 5.
--
-- Generated by `scripts/generateWordEfficiencyMigration.ts` from
-- `src/exam/papers/wordEfficiency.ts`, which is what `wordEfficiency.test.ts`
-- marks question by question. Edit the paper and regenerate; do not edit this
-- file by hand, or the papers that were tested and the papers that ship stop
-- being the same papers.
--
-- Idempotent: a re-run replaces both papers' questions rather than adding a
-- second copy, and leaves every other paper alone.
--
-- Statements are separated the way drizzle-kit separates them, with the marker
-- it splits a file on. Without those markers the whole file is sent as one
-- query, which node-postgres allows and other drivers do not — and a migration
-- that depends on the driver is a migration that works until it does not.
--
-- The marker is deliberately not written out in this comment: the split is a
-- plain string search, so a comment naming it is cut in half and its second
-- half is fed to Postgres as SQL. That is exactly what happened here once.

-- The papers hang off an exam, and which one decides what the mock list calls
-- them. The oldest *published* exam is the candidate-facing one, so that is
-- preferred; an unpublished one is used only when there is nothing else, and on
-- a fresh database one is created — published, or the papers would be listed
-- under an exam nobody can see.
INSERT INTO exams (id, name, slug, category, organiser_name, description, status)
SELECT
  gen_random_uuid(),
  'SSC CGL',
  'ssc-cgl',
  'SSC',
  'Staff Selection Commission',
  'Combined Graduate Level examination.',
  'published'
WHERE NOT EXISTS (SELECT 1 FROM exams);
--> statement-breakpoint

WITH host_exam AS (
  SELECT id
  FROM exams
  -- Published first, then oldest: false sorts before true, so this reads as
  -- "published before everything else" without naming the statuses twice.
  ORDER BY (status <> 'published'), created_at ASC
  LIMIT 1
),
upserted AS (
  INSERT INTO tests (
    id, exam_id, name, slug, subject, section_name, tagline, duration_minutes, qualifying_marks, status
  )
  VALUES
  (
    gen_random_uuid(),
    (SELECT id FROM host_exam),
    'Word Efficiency Test : 4',
    'word-efficiency-test-4',
    'word',
    'Word Processing',
    'Formatting drill on a district notice — replace, highlight, underline, indent.',
    20,
    10,
    'published'
  ),
  (
    gen_random_uuid(),
    (SELECT id FROM host_exam),
    'Word Efficiency Test : 5',
    'word-efficiency-test-5',
    'word',
    'Word Processing',
    'Formatting drill on a company circular — effects, borders, spacing, lists.',
    20,
    10,
    'published'
  )
  ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    section_name = EXCLUDED.section_name,
    tagline = EXCLUDED.tagline,
    duration_minutes = EXCLUDED.duration_minutes,
    qualifying_marks = EXCLUDED.qualifying_marks,
    status = EXCLUDED.status,
    updated_at = now()
  RETURNING id, slug
)
SELECT 1 FROM upserted;
--> statement-breakpoint

-- The questions are replaced wholesale: a paper's positions must run 1..n with
-- no gaps, and reconciling them one by one would leave a half-updated paper if
-- anything failed in the middle.
DELETE FROM test_questions
WHERE test_id IN (SELECT id FROM tests WHERE slug IN ('word-efficiency-test-4', 'word-efficiency-test-5'));
--> statement-breakpoint

